from fastapi import FastAPI, HTTPException
from datetime import datetime, timedelta

app = FastAPI()
rate_limits = {}  # user_id: {'tokens': int, 'reset_at': datetime}
RATE_LIMIT = 100  # 100 requests
WINDOW = 60  # per 60 seconds

def check_rate_limit(user_id: str) -> bool:
    now = datetime.now()
    if user_id not in rate_limits:
        rate_limits[user_id] = {'tokens': RATE_LIMIT, 'reset_at': now + timedelta(seconds=WINDOW)}

    limit = rate_limits[user_id]
    if now >= limit['reset_at']:
        limit['tokens'] = RATE_LIMIT
        limit['reset_at'] = now + timedelta(seconds=WINDOW)

    if limit['tokens'] <= 0:
